ALTER TABLE public.fund_settings ADD CONSTRAINT fund_weights_nonnegative CHECK(audience_weight>=0 AND production_weight>=0 AND completion_weight>=0);
CREATE OR REPLACE FUNCTION public.calculate_author_fund(_month date) RETURNS TABLE(fund_type text,owner_id uuid,course_id uuid,title text,eligible_minutes numeric,approved_minutes numeric,completion numeric,audience numeric,production numeric,score numeric,estimated_cents bigint) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$
WITH daily AS(SELECT v.user_id,v.lesson_id,v.viewed_on,least(sum(v.seconds_watched) FILTER(WHERE v.seconds_watched>=20),max(l.duration_min)*60) seconds FROM public.lesson_views v JOIN public.lessons l ON l.id=v.lesson_id WHERE v.viewed_on>=_month AND v.viewed_on<_month+interval '1 month' GROUP BY v.user_id,v.lesson_id,v.viewed_on),
viewed AS(SELECT lesson_id,sum(seconds)/60.0 minutes FROM daily GROUP BY lesson_id HAVING sum(seconds)>0),
base AS(SELECT CASE WHEN c.institution_id IS NULL THEN 'professor' ELSE 'ies' END kind,COALESCE(c.institution_id,c.instructor_id) owner,c.id cid,c.title heading,sum(v.minutes) watched,sum(l.duration_min) FILTER(WHERE v.lesson_id IS NOT NULL)::numeric produced FROM public.courses c JOIN public.lessons l ON l.course_id=c.id LEFT JOIN viewed v ON v.lesson_id=l.id WHERE c.status='publicado' AND c.published AND (c.institution_id IS NOT NULL OR c.instructor_id IS NOT NULL) GROUP BY c.id HAVING sum(v.minutes)>0),
first_pass AS(SELECT a.user_id,a.profile_role,a.module_id,min(a.created_at) passed_at FROM public.assessment_attempts a WHERE a.passed GROUP BY a.user_id,a.profile_role,a.module_id),
finished AS(SELECT f.user_id,f.profile_role,m.course_id,max(f.passed_at) finished_at FROM first_pass f JOIN public.course_modules m ON m.id=f.module_id GROUP BY f.user_id,f.profile_role,m.course_id HAVING count(*)=(SELECT count(*) FROM public.course_modules cm WHERE cm.course_id=m.course_id)),
completions AS(SELECT course_id,count(*)::numeric n FROM finished WHERE finished_at>=_month AND finished_at<_month+interval '1 month' GROUP BY course_id),
raw AS(SELECT b.*,COALESCE(c.n,0) completed FROM base b LEFT JOIN completions c ON c.course_id=b.cid),
shares AS(SELECT r.*,watched/NULLIF(sum(watched) OVER(PARTITION BY kind),0) aud,produced/NULLIF(sum(produced) OVER(PARTITION BY kind),0) prod,COALESCE(completed/NULLIF(sum(completed) OVER(PARTITION BY kind),0),0) comp FROM raw r),
weighted AS(SELECT sh.*,s.audience_weight*aud+s.production_weight*prod+s.completion_weight*comp weighted_score FROM shares sh CROSS JOIN public.fund_settings s),
normalized AS(SELECT w.*,weighted_score/NULLIF(sum(weighted_score) OVER(PARTITION BY kind),0) final_score FROM weighted w),
revenue AS(SELECT greatest(COALESCE(sum(amount_cents),0),0)::numeric total FROM public.payments WHERE status='pago' AND paid_at>=_month AND paid_at<_month+interval '1 month'),
allocation AS(SELECT n.*,round(r.total*CASE WHEN kind='professor' THEN .25 ELSE .10 END)::bigint fund,COALESCE(final_score,0)*round(r.total*CASE WHEN kind='professor' THEN .25 ELSE .10 END) exact_amount FROM normalized n CROSS JOIN revenue r),
rounded AS(SELECT a.*,floor(exact_amount)::bigint floor_amount,row_number() OVER(PARTITION BY kind ORDER BY exact_amount-floor(exact_amount) DESC,cid) remainder_rank FROM allocation a)
SELECT kind,owner,cid,heading,round(watched,2),produced,comp,aud,prod,COALESCE(final_score,0),floor_amount+CASE WHEN final_score>0 AND remainder_rank<=fund-sum(floor_amount) OVER(PARTITION BY kind) THEN 1 ELSE 0 END FROM rounded $$;
REVOKE ALL ON FUNCTION public.calculate_author_fund(date) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.author_metrics(_month date DEFAULT date_trunc('month',now())::date) RETURNS TABLE(fund_type text,owner_id uuid,course_id uuid,title text,eligible_minutes numeric,approved_minutes numeric,completion numeric,audience numeric,production numeric,score numeric,estimated_cents bigint) LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR _month IS NULL OR date_trunc('month',_month)::date<>_month THEN RAISE EXCEPTION 'Mês inválido'; END IF; RETURN QUERY SELECT c.* FROM public.calculate_author_fund(_month) c WHERE (c.fund_type='professor' AND c.owner_id=auth.uid() AND public.current_profile_role()='professor') OR (c.fund_type='ies' AND public.organization_permission(c.owner_id,'ies','financeiro')) OR (public.is_admin() AND public.current_profile_role() NOT IN('professor','ies','empresa','colaborador')); END $$;
CREATE OR REPLACE FUNCTION public.close_month(_month date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE total bigint; s public.fund_settings; BEGIN IF NOT public.is_admin() OR public.current_profile_role() IN('professor','ies','empresa','colaborador') THEN RAISE EXCEPTION 'Fechamento administrativo necessário'; END IF; IF _month IS NULL OR date_trunc('month',_month)::date<>_month OR _month>=date_trunc('month',now())::date THEN RAISE EXCEPTION 'Feche somente meses encerrados'; END IF; SELECT greatest(COALESCE(sum(amount_cents),0),0) INTO total FROM public.payments WHERE status='pago' AND paid_at>=_month AND paid_at<_month+interval '1 month'; SELECT * INTO s FROM public.fund_settings; INSERT INTO public.monthly_funds VALUES(_month,total,round(total*.25),round(total*.10),to_jsonb(s),now()); INSERT INTO public.author_scores(month,owner_id,fund_type,audience,production,completion,final_score,amount_cents) SELECT _month,c.owner_id,c.fund_type,sum(c.audience),sum(c.production),sum(c.completion),sum(c.score),sum(c.estimated_cents) FROM public.calculate_author_fund(_month) c GROUP BY c.fund_type,c.owner_id; END $$;
CREATE POLICY author_scores_financial_guard ON public.author_scores AS RESTRICTIVE FOR SELECT TO authenticated USING((fund_type='professor' AND owner_id=auth.uid() AND public.current_profile_role()='professor') OR (fund_type='ies' AND public.organization_permission(owner_id,'ies','financeiro')) OR (public.is_admin() AND public.current_profile_role() NOT IN('professor','ies','empresa','colaborador')));
REVOKE EXECUTE ON FUNCTION public.organization_owner(uuid,text),public.organization_permission(uuid,text,text,uuid),public.organization_member(uuid,text),public.can_validate_student(uuid,uuid),public.is_admin(),public.has_role(uuid,public.app_role),public.current_profile_role() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.organization_owner(uuid,text),public.organization_permission(uuid,text,text,uuid),public.organization_member(uuid,text),public.can_validate_student(uuid,uuid),public.is_admin(),public.has_role(uuid,public.app_role),public.current_profile_role() TO authenticated;
GRANT EXECUTE ON FUNCTION public.current_profile_role(),public.organization_permission(uuid,text,text,uuid),public.is_admin(),public.organization_member(uuid,text) TO anon;